/* Native 320px composition: geometry first, controls second. */
.d-constellation-demo{position:relative;height:320px;min-height:0;padding:16px;box-sizing:border-box;overflow:hidden;background:#0a0a0b;color:#ececef}
.d-constellation-demo>header,.d-constellation-demo>[class$="-head"]{display:none}
.d-constellation-stage{height:248px;min-height:0;margin:0;box-sizing:border-box;border:0;background:#0a0a0b}
.d-constellation-demo [class$="-guide"],.d-constellation-demo [class$="-note"],.d-constellation-demo [class$="-spec"],.d-constellation-demo [class$="-hud"],.d-constellation-stage>p{display:none}
.d-constellation-demo footer,.d-constellation-demo>[class$="-foot"]{display:flex;justify-content:center;align-items:center;gap:6px;margin:10px 0 0}
.d-constellation-demo footer button,.d-constellation-demo>[class$="-foot"] button{min-height:28px;padding:6px 8px;border:1px solid #333;border-radius:0;background:#161619;color:#b8b8b8;font:500 9px/1.15 'Roboto Mono',monospace;letter-spacing:0}
.d-constellation-demo footer button:hover,.d-constellation-demo footer button:focus-visible,.d-constellation-demo>[class$="-foot"] button:hover,.d-constellation-demo>[class$="-foot"] button:focus-visible{background:#262626;color:#fa7319;border-color:#fa7319;outline:none}
.d-constellation-demo>[class$="-foot"]>p{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}

.d-constellation-demo footer{flex-wrap:nowrap;gap:5px}.d-constellation-demo footer>button{flex:0 1 auto;min-width:0;white-space:normal;min-height:28px}.d-constellation-stage{height:240px}

/* Material and typography refinement: calm light, fine edges, purposeful type. */
.d-constellation-demo{--demo-sans:Manrope,system-ui,sans-serif;--demo-serif:Newsreader,Georgia,serif;font-family:var(--demo-sans)}
.d-constellation-demo button,.d-constellation-demo footer button,.d-constellation-demo>[class$="-foot"] button{font-family:var(--demo-sans);font-size:10px;font-weight:500;line-height:1.2;letter-spacing:.005em;text-transform:none}
